package tv.vela.launcher;

import android.app.*;import android.content.*;import android.graphics.*;import android.os.*;import android.view.*;import android.widget.*;import java.io.*;import java.lang.reflect.*;import java.util.*;

/** Synthetic TV metadata through the same resolver and lifecycle as real hardware. No physical devices are changed. */
public final class AndroidInputsTest extends Instrumentation {
    private HomeActivity activity;private String phase="setup";
    static final class Source implements TvInputs.Source {
        final Context context;Runnable listener;int starts,stops;List<TvInputs.Raw> raw=new ArrayList<>();
        Source(Context c){context=c;for(int n=1;n<=6;n++)raw.add(new TvInputs.Raw("port"+n,null,"HDMI "+n,"",n==3?TvInputs.DISCONNECTED:n==5?TvInputs.STANDBY:TvInputs.CONNECTED));raw.add(new TvInputs.Raw("switch","port1","Nintendo Switch","",TvInputs.CONNECTED));raw.add(new TvInputs.Raw("ps5","port2","PlayStation 5","",TvInputs.CONNECTED));raw.add(new TvInputs.Raw("ps3","port3","PLAYSTATION 3","",TvInputs.CONNECTED));raw.add(new TvInputs.Raw("ps2","port4","PS2","",TvInputs.CONNECTED));raw.add(new TvInputs.Raw("ps4","port5","PlayStation 4","",TvInputs.STANDBY));}
        public List<TvInputs.Entry> read(){return TvInputs.resolve(context,raw);}public void start(Runnable changed){starts++;listener=changed;}public void stop(){stops++;listener=null;}
        void change(){if(listener!=null)listener.run();}
    }
    public static final class Home extends HomeActivity {Source source;TvInputs.Source createInputsSource(){source=new Source(this);return source;}}
    private Home created;
    public Activity newActivity(ClassLoader cl,String name,Intent intent)throws InstantiationException,IllegalAccessException,ClassNotFoundException{if(name.equals(HomeActivity.class.getName())){created=new Home();return created;}return super.newActivity(cl,name,intent);}
    Object field(Object o,String name)throws Exception{for(Class<?> c=o.getClass();c!=null;c=c.getSuperclass())try{Field f=c.getDeclaredField(name);f.setAccessible(true);return f.get(o);}catch(NoSuchFieldException e){}throw new NoSuchFieldException(name);}
    void check(boolean value,String why){if(!value)throw new AssertionError(why);}
    void ui(Runnable r){runOnMainSync(r);waitForIdleSync();}
    void key(int code){sendKeyDownUpSync(code);waitForIdleSync();}
    void click(View v){ui(v::requestFocus);key(KeyEvent.KEYCODE_DPAD_CENTER);}
    void shot(String name)throws Exception{Thread.sleep(350);Bitmap image=getUiAutomation().takeScreenshot();check(image!=null&&image.getWidth()==3840&&image.getHeight()==2160,"Native 4K screenshot required");try(OutputStream file=new FileOutputStream(new File(getTargetContext().getExternalFilesDir(null),name+".png"))){image.compress(Bitmap.CompressFormat.PNG,100,file);}finally{image.recycle();}}
    View text(View view,String text){if(view instanceof TextView&&((TextView)view).getText().toString().equals(text))return view;if(view instanceof ViewGroup)for(int n=0;n<((ViewGroup)view).getChildCount();n++){View found=text(((ViewGroup)view).getChildAt(n),text);if(found!=null)return found;}return null;}
    void restore(SharedPreferences p,Map<String,?> values){SharedPreferences.Editor e=p.edit().clear();for(Map.Entry<String,?> entry:values.entrySet()){Object v=entry.getValue();if(v instanceof Boolean)e.putBoolean(entry.getKey(),(Boolean)v);else if(v instanceof String)e.putString(entry.getKey(),(String)v);else if(v instanceof Integer)e.putInt(entry.getKey(),(Integer)v);else if(v instanceof Long)e.putLong(entry.getKey(),(Long)v);else if(v instanceof Float)e.putFloat(entry.getKey(),(Float)v);}e.commit();}
    public void onCreate(Bundle args){super.onCreate(args);start();}
    public void onStart(){Bundle result=new Bundle();Context c=getTargetContext();Map<SharedPreferences,Map<String,?>> saved=new LinkedHashMap<>();ActivityMonitor monitor=null;try{
        check(Build.MODEL.contains("sdk")||Build.FINGERPRINT.contains("generic"),"Owned emulator required");check(!new PlexClient(c).connected()&&!new JellyfinClient(c).connected()&&!new XtreamClient(c).connected(),"No personal accounts allowed");for(SharedPreferences p:new SharedPreferences[]{TvInputs.prefs(c),Personalization.prefs(c),Visuals.prefs(c),Updates.prefs(c),AmbientWeather.prefs(c)})saved.put(p,new HashMap<>(p.getAll()));TvInputs.prefs(c).edit().clear().commit();Personalization.complete(c);Appearance.set(c,"color",0);Updates.prefs(c).edit().putBoolean("automatic",false).putBoolean("download",false).commit();AmbientWeather.select(c,new AmbientWeather.Place("Reikiavik · Demo","",64.15,-21.94,"Atlantic/Reykjavik"));
        phase="vectors";for(Field drawable:R.drawable.class.getFields())if(drawable.getName().startsWith("device_"))check(c.getDrawable(drawable.getInt(null)) instanceof android.graphics.drawable.VectorDrawable,"Invalid native device vector: "+drawable.getName());
        phase="metadata";Source data=new Source(c);List<TvInputs.Entry> entries=data.read();check(entries.size()==6,"Parent and CEC inputs duplicated ports");check(entries.get(0).model.equals("switch")&&entries.get(0).inputId.equals("switch"),"Switch CEC identity not used");check(entries.get(1).model.equals("ps5")&&entries.get(2).state==TvInputs.DISCONNECTED&&entries.get(2).title.equals("HDMI 3")&&entries.get(2).model.equals("other"),"Stale CEC child claimed a live connection");check(entries.get(4).state==TvInputs.STANDBY&&entries.get(4).title.equals("HDMI 5")&&entries.get(4).model.equals("other")&&entries.get(5).title.equals("HDMI 6"),"Standby or unknown device misreported");check(TvInputs.detect("PlayStation").equals("playstation")&&TvInputs.detect("HDMI 4").equals("other")&&TvInputs.detect("PS4 Pro").equals("ps4"),"Console generation guessed or explicit model missed");
        check(TvInputs.detect("Xbox One X").equals("xboxonex")&&TvInputs.detect("Xbox One S").equals("xboxones")&&TvInputs.detect("Xbox 360").equals("xbox360")&&TvInputs.detect("Xbox Series S").equals("xboxseriess")&&TvInputs.detect("Nintendo Switch OLED").equals("switcholed")&&TvInputs.detect("Chromecast").equals("chromecast"),"Extended profiles not recognized");
        List<TvInputs.Raw> orphan=Arrays.asList(new TvInputs.Raw("orphan","absent","PlayStation 2","",TvInputs.CONNECTED));check(TvInputs.resolve(c,orphan).size()==1,"Missing physical parent lost a reported device");
        activity=(HomeActivity)startActivitySync(new Intent(c,HomeActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));Object home=field(activity,"home");List<View> nav=(List<View>)field(home,"sideButtons");click(nav.get(5));HomeScreenHost host=(HomeScreenHost)field(home,"panels");InputsScreen screen=(InputsScreen)host.screen;Source source=created.source;List<View> cards=(List<View>)field(screen,"cards");check(cards.size()==6&&source.listener!=null,"Cards or hardware subscription missing");check(((ViewGroup)cards.get(1)).getChildAt(0).getBackground()!=null,"Integration removed the card background");Thread.sleep(600);waitForIdleSync();Object imageLoader=field(screen,"icons");check(((ImageView)field(screen,"heroIcon")).getDrawable() instanceof android.graphics.drawable.VectorDrawable,"Active console icon is not an original native vector");shot("inputs-01-devices");
        phase="launch";IntentFilter filter=new IntentFilter(Intent.ACTION_VIEW);filter.addDataScheme("content");monitor=addMonitor(filter,new ActivityResult(Activity.RESULT_CANCELED,null),true);click(cards.get(0));check(monitor.getHits()==1,"HDMI card did not send passthrough playback request");removeMonitor(monitor);monitor=null;
        phase="remote";ui(cards.get(0)::requestFocus);key(KeyEvent.KEYCODE_DPAD_RIGHT);check(cards.get(1).hasFocus(),"Right did not select next HDMI card");key(KeyEvent.KEYCODE_DPAD_LEFT);check(cards.get(0).hasFocus(),"Left skipped a card");key(KeyEvent.KEYCODE_DPAD_LEFT);check(nav.get(5).hasFocus(),"Left edge did not return to sidebar");key(KeyEvent.KEYCODE_DPAD_RIGHT);check(cards.contains(activity.getCurrentFocus()),"Right did not return to inputs");
        phase="personalize";ui(cards.get(5)::requestFocus);sendKeySync(new KeyEvent(0,0,KeyEvent.ACTION_DOWN,KeyEvent.KEYCODE_DPAD_CENTER,0));Thread.sleep(ViewConfiguration.getLongPressTimeout()+200);sendKeySync(new KeyEvent(KeyEvent.ACTION_UP,KeyEvent.KEYCODE_DPAD_CENTER));waitForIdleSync();check((Boolean)field(screen,"picking"),"Long OK was swallowed or accepted a device immediately");shot("inputs-02-choose-device");View ps3=text(screen.content,"PlayStation 3");check(ps3!=null,"Model chooser missing PS3");click(ps3);check(TvInputs.preset(c,"port6").equals("ps3")&&source.read().get(5).model.equals("ps3"),"Assignment did not persist by physical port");
        phase="hotplug";cards=(List<View>)field(screen,"cards");ui(cards.get(1)::requestFocus);ui(()->{source.raw.removeIf(r->r.id.equals("ps5"));source.raw.set(1,new TvInputs.Raw("port2",null,"HDMI 2","",TvInputs.DISCONNECTED));source.change();});Thread.sleep(250);waitForIdleSync();check(activity.getCurrentFocus().getContentDescription().toString().contains("HDMI 2")&&activity.getCurrentFocus().getContentDescription().toString().contains("Sin conexión"),"Hardware refresh lost focus or retained stale connection");
        ui(()->source.change());Thread.sleep(250);waitForIdleSync();ui(()->{try{((List<View>)field(screen,"cards")).get(0).requestFocus();}catch(Exception e){throw new RuntimeException(e);}});shot("inputs-03-personalized");
        phase="lifecycle";click(nav.get(0));check(source.listener==null&&!(Boolean)field(screen,"active")&&(Boolean)field(imageLoader,"closed")&&((Set<?>)field(imageLoader,"bound")).isEmpty(),"Hardware listener retained after leaving Inputs");click(nav.get(5));check(created.source.listener!=null&&TvInputs.preset(c,"port6").equals("ps3"),"Reopening inputs lost assignment");
        phase="xbox-showcase";HomeScreenHost reopened=(HomeScreenHost)field(home,"panels");InputsScreen xboxScreen=(InputsScreen)reopened.screen;Source xboxSource=created.source;
        ui(()->{TvInputs.assign(c,"port6","auto");xboxSource.raw.add(new TvInputs.Raw("xboxseriesx","port6","Xbox Series X","",TvInputs.CONNECTED));xboxSource.change();});Thread.sleep(250);waitForIdleSync();ui(()->{try{((List<View>)field(xboxScreen,"cards")).get(5).requestFocus();}catch(Exception e){throw new RuntimeException(e);}});Thread.sleep(500);waitForIdleSync();check(((TextView)field(xboxScreen,"heroName")).getText().toString().equals("Xbox Series X"),"Showcase did not follow Xbox focus");check(((ImageView)field(xboxScreen,"heroIcon")).getDrawable()!=null,"Xbox brand vector missing");shot("inputs-04-xbox-featured");
        check(((ImageView)field(xboxScreen,"heroIcon")).getDrawable() instanceof android.graphics.drawable.VectorDrawable,"Xbox icon unexpectedly allocates a photo bitmap");

        result.putString("result","PASS six deduplicated ports with Switch/PS2/PS3/PS4/PS5/unknown metadata, CEC launch target, stale child disconnected, standby honesty, explicit model detection, missing parent, real remote grid/long OK/assignment, refresh preserves focus, native passthrough request intercepted, callback release/reopen, Xbox showcase and native brand vectors without photo workers or caches. Four native 4K screenshots use simulated input metadata; no physical console detection or TV setting changes claimed.");
    }catch(Throwable error){result.putString("phase",phase);result.putString("error",android.util.Log.getStackTraceString(error));}finally{if(monitor!=null)removeMonitor(monitor);if(activity!=null)ui(activity::finish);for(Map.Entry<SharedPreferences,Map<String,?>> entry:saved.entrySet())restore(entry.getKey(),entry.getValue());}finish(result.containsKey("error")?1:-1,result);}
}
